sp_widget.css:
/* ---------- Top bar ---------- */
.clm-topbar-custom {
  display: flex;
  justify-content: space-between; 
  align-items: center;
  height: 48px;
  background: var(--ut-black, #1a1a1a);
  border-bottom: 3px solid #f5c400;
  padding: 0 16px;
  gap: 12px;
  flex-shrink: 0;
}

/* Logo Section */
.sn-logo-badge {
  background: #f5c400;
  padding: 4px 8px;
  border-radius: 4px;
  display: flex;
  flex-direction: column;
  line-height: 1.1;
}

.sn-logo-text {
  font-weight: 800;
  font-size: 15px;
  color: #14141a;
}

.sn-logo-sub {
  font-size: 8px;
  font-weight: 700;
  color: #1a1a1a;
  letter-spacing: .08em;
}

/* Module Texts */
.sn-topbar-module {
  font-size: 13px;
  font-weight: 600;
  color: #fff;
}

.sn-topbar-view {
  font-size: 13px;
  font-weight: 400;
  color: #a0aec0;
}

/* Right Group */
.topbar-right {
  display: flex;
  align-items: center;
}

.live-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #3bb273;
  margin-right: 6px;
}

.live-text {
  color: #3bb273;
  font-size: 13px;
  margin-right: 24px;
}

.avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: #f5c400;
  color: #14141a;
  font-weight: 700;
  font-size: 13px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-right: 10px;
}

.user-name {
  font-weight: 500;
  font-size: 13px;
  color: #ffffff;
}

sp_widget.script:
(function() {
    // 1. Dynamic Date Logic
    var gdt = new GlideDateTime();
    var months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

    // getMonthLocalTime() returns 1-12, so we subtract 1 for the array index
    var monthIndex = gdt.getMonthLocalTime() - 1; 
    var year = gdt.getYearLocalTime();

    data.liveDateText = months[monthIndex] + ' ' + year;

    // 2. User Profile Logic
    data.userName = gs.getUserDisplayName();
    data.userInitials = '';

    if (data.userName) {
        var names = data.userName.split(' ');
        if (names.length > 1) {
            data.userInitials = names[0].charAt(0).toUpperCase() + names[names.length - 1].charAt(0).toUpperCase();
        } else {
            data.userInitials = names[0].charAt(0).toUpperCase();
        }
    }
})();
